const t=new class{constructor(){this.storageKey="yph_system_logs",this.maxEntries=1e3}async getLogs(){if("undefined"==typeof browser)return[];return(await browser.storage.local.get(this.storageKey))[this.storageKey]||[]}async saveLogs(t){if("undefined"==typeof browser)return;await browser.storage.local.set({[this.storageKey]:t});const e=new CustomEvent("system-log-updated",{detail:t[t.length-1]});window.dispatchEvent(e)}async append(t){const e=await this.getLogs();e.push(t),e.length>this.maxEntries&&e.splice(0,e.length-this.maxEntries),await this.saveLogs(e)}format(t,e,s){return{timestamp:(new Date).toISOString(),module:t,level:"INFO",action:e,details:s}}async info(t,e,s){const a=this.format(t,e,s);a.level="INFO",await this.append(a)}async warn(t,e,s){const a=this.format(t,e,s);a.level="WARN",await this.append(a)}async error(t,e,s){const a=this.format(t,e,s);a.level="ERROR",await this.append(a)}};"undefined"!=typeof window&&(window.SystemLogger=t);export{t as S};
